def empirical_probability(count_event: int, count_trials: int) -> float:
    """Return empirical probability count_event / count_trials. Caller is responsible for large n -> convergence."""
    if count_trials <= 0:
        raise ValueError("count_trials must be positive")
    return count_event / count_trials

import math

def comb(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def probability_equally_likely(count_favorable: int, count_total: int) -> float:
    if count_total <= 0:
        raise ValueError("count_total must be positive")
    if not (0 <= count_favorable <= count_total):
        raise ValueError("count_favorable must be between 0 and count_total")
    return count_favorable / count_total

def probability_pocket_aces() -> float:
    favorable = comb(4, 2)
    total = comb(52, 2)
    return favorable / total

def prob_union_disjoint(probs):
    """Sum probabilities for a collection of mutually exclusive events."""
    if any(p < 0 or p > 1 for p in probs):
        raise ValueError("All probabilities must be between 0 and 1")
    s = sum(probs)
    if s > 1 + 1e-9:
        raise ValueError("Sum of disjoint probabilities cannot exceed 1")
    return s

from typing import Sequence

def expected_value(probabilities: Sequence[float], values: Sequence[float]) -> float:
    if len(probabilities) != len(values):
        raise ValueError("probabilities and values must have same length")
    if any(p < 0 or p > 1 for p in probabilities):
        raise ValueError("probabilities must be in [0,1]")
    if abs(sum(probabilities) - 1.0) > 1e-6:
        raise ValueError("probabilities must sum to 1")
    return sum(p * v for p, v in zip(probabilities, values))

from typing import Dict, Callable, Any

def range_vs_range_ev(P_H: Dict[Any, float],
                      P_V: Dict[Any, float],
                      P_B: Dict[Any, float],
                      payoff_fn: Callable[[Any, Any, Any], float]) -> float:
    """Compute EV given hero range P_H, villain range P_V, board distribution P_B, and a payoff function
    that is already implied by fixed strategies σ_H, σ_V.
    Keys of P_H/P_V/P_B can be arbitrary hashables representing hands/boards."""
    # Basic checks (optional for performance)
    if abs(sum(P_H.values()) - 1.0) > 1e-6:
        raise ValueError("P_H must sum to 1")
    if abs(sum(P_V.values()) - 1.0) > 1e-6:
        raise ValueError("P_V must sum to 1")
    if abs(sum(P_B.values()) - 1.0) > 1e-6:
        raise ValueError("P_B must sum to 1")
    ev = 0.0
    for h, ph in P_H.items():
        for v, pv in P_V.items():
            for b, pb in P_B.items():
                ev += ph * pv * pb * payoff_fn(h, v, b)
    return ev

def p_union(pA: float, pB: float, pA_intersect_B: float) -> float:
    """Return p(A ∪ B) given p(A), p(B), p(A ∩ B)."""
    return pA + pB - pA_intersect_B

def p_intersect_independent(pA: float, pB: float) -> float:
    """Return p(A ∩ B) for independent A,B."""
    return pA * pB

def p_intersect_dependent(pA: float, pB_given_A: float) -> float:
    """Return p(A ∩ B) = p(A) p(B|A)."""
    return pA * pB_given_A

def p_complement(pA: float) -> float:
    """Return p(Ā) = 1 - p(A)."""
    return 1.0 - pA

