from typing import Sequence, Tuple

def expected_value(outcomes: Sequence[Tuple[float, float]]) -> float:
    """Return EV given (value, probability) pairs; probabilities should sum to 1.

    outcomes: list of (v_i, p_i)
    """
    return sum(v * p for v, p in outcomes)

# Convenience wrappers for the examples

