from typing import Sequence

def ev_scaled(outcomes: Sequence[Tuple[float, float]], c: float) -> float:
    """EV after scaling all outcome values by c."""
    base_ev = expected_value(outcomes)
    return c * base_ev

def ev_shifted(outcomes: Sequence[Tuple[float, float]], d: float) -> float:
    """EV after adding constant d to all outcome values."""
    base_ev = expected_value(outcomes)
    return base_ev + d

def ev_sum_of_trials(evs: Sequence[float]) -> float:
    """Total EV over multiple trials with given per-trial EVs."""
    return sum(evs)

