from collections import Counter
from typing import Hashable

Outcome = Hashable

def normalize_counts_to_distribution(counts: Dict[Outcome, int]) -> Dict[Outcome, float]:
    """Convert raw counts (e.g., combo counts) into a probability distribution."""
    total = sum(counts.values())
    return {o: c / total for o, c in counts.items()}

def coarsen_distribution(dist: Dict[Outcome, float],
                         map_fn: Callable[[Outcome], Outcome]) -> Dict[Outcome, float]:
    """Aggregate a fine-grained distribution into a coarser one via map_fn."""
    agg = Counter()
    for outcome, p in dist.items():
        agg[map_fn(outcome)] += p
    total = sum(agg.values())
    return {o: p / total for o, p in agg.items()}

def prob_to_odds_against(p: float) -> float:
    """Convert probability p to numeric odds against (o such that odds are o:1)."""
    if p <= 0 or p >= 1:
        raise ValueError("p must be in (0,1) for odds conversion")
    return (1 - p) / p

def odds_against_to_prob(o: float) -> float:
    """Convert numeric odds against o (o:1) to probability p."""
    if o < 0:
        raise ValueError("odds must be non-negative")
    return 1.0 / (1.0 + o)

def breakeven_call_equity(bet: float, pot: float) -> float:
