import math

def normal_cdf(z):
    """Standard normal CDF Φ(z) using error function approximation."""
    return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))

def normal_tail_prob(x, mu, sigma, side="right"):
    """Approx tail prob for X ~ Normal(mu, sigma).
    side: 'right' for P(X>=x), 'left' for P(X<=x), 'two' for two-sided |X-mu|>=|x-mu|
    """
    z = (x - mu) / sigma
    if side == "right":
        return 1.0 - normal_cdf(z)
    elif side == "left":
        return normal_cdf(z)
    elif side == "two":
        if z >= 0:
            return 2.0 * (1.0 - normal_cdf(z))
        else:
            return 2.0 * normal_cdf(z)
    else:
        raise ValueError("side must be 'right', 'left', or 'two'")

def prob_session_win(mu_per_hand, sigma_per_hand, n_hands):
    """Approximate probability session result > 0 using normal approximation."""
    import math
    def normal_cdf(z):
        return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))
    mu_N = mu_per_hand * n_hands
    sigma_N = sigma_per_hand * (n_hands ** 0.5)
    z0 = (0.0 - mu_N) / sigma_N
    return 1.0 - normal_cdf(z0)

def prob_reach_target(mu_per_trial, sigma_per_trial, n_trials, target):
    """Approximate P(total >= target) for N trials using normal approximation."""
    import math
    def normal_cdf(z):
        return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))
    mu_N = mu_per_trial * n_trials
    sigma_N = sigma_per_trial * (n_trials ** 0.5)
    z = (target - mu_N) / sigma_N
    return 1.0 - normal_cdf(z)

def bernoulli_stats(p):
    """Return (mu, variance, sigma) for Bernoulli(p) with outcomes 0/1."""
    mu = p
    var = p * (1.0 - p)
    sigma = var ** 0.5
    return mu, var, sigma

def bernoulli_sample_std(p, n_trials):
    """Std dev of number of successes in N Bernoulli(p) trials."""
    _, var, _ = bernoulli_stats(p)
    return (n_trials * var) ** 0.5

def bernoulli_deviation_p_value(p, n_trials, x_obs, side="two"):
    """Approximate p-value for observing x_obs successes in N Bernoulli(p) trials.
    side: 'left', 'right', or 'two' for two-sided.
    """
    import math
    def normal_cdf(z):
        return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))
    mu_N = p * n_trials
    sigma_N = math.sqrt(n_trials * p * (1.0 - p))
    z = (x_obs - mu_N) / sigma_N
    if side == "left":
        return normal_cdf(z)
    elif side == "right":
        return 1.0 - normal_cdf(z)
    elif side == "two":
        if z >= 0:
            return 2.0 * (1.0 - normal_cdf(z))
        else:
            return 2.0 * normal_cdf(z)
    else:
        raise ValueError("side must be 'left', 'right', or 'two'")

import math

def winrate_sd_per_100(sigma_per_hand: float, N_hands: int) -> float:
    """Return SD of observed winrate (units per 100 hands) over N hands.

    sigma_per_hand: SD per hand (same units as desired winrate unit, e.g., BB/hand).
