def mle_mean_normal(sample):
    """Return the maximum likelihood estimate of the mean for a normal sample."""
    return sum(sample) / len(sample) if sample else 0.0

def bayes_update_sequence(prior, likelihoods):
    """Generic multi-type Bayesian update.
    prior: dict {type: p(type)}
    likelihoods: list of dicts, one per observation, each {type: p(A_i | type)}
    Returns updated posterior dict.
    """
    posterior = prior.copy()
    for like in likelihoods:
        # Multiply by likelihood of current observation
        for t in posterior:
            posterior[t] *= like.get(t, 0.0)
        # Normalize
        total = sum(posterior.values())
        if total == 0:
            # Degenerate case: no support; return unnormalized
            return posterior
        for t in posterior:
            posterior[t] /= total
    return posterior

def ev_single_street_call(p_win: float, pot: float, bet: float, call: float) -> float:
    """EV of calling once with a draw vs known made hand, no more betting.
    pot: size before bet, bet: villain's bet, call: our call size (often = bet).
    """
    new_pot = pot + bet + call
    return p_win * new_pot - call

def min_equity_for_call(pot: float, bet: float, call: float) -> float:
    """Minimum p_win to make a single-street call non-negative EV."""
    return call / (pot + bet + call)

def equity_threshold_limit_call(pot: float, bet: float) -> float:
    """Heads-up limit: facing a single bet, no raises, final pot = pot + 2*bet.
    Returns min equity to call.
    """
    return bet / (pot + 2*bet)

def mdf_from_pot_bet(pot: float, bet: float) -> float:
    """Minimum defense frequency x* = P / (P + b)."""
