def river_call_ev_polarized(pot: float, bet: float, value_prob: float) -> float:
    """EV of calling vs a polarized bet: villain is value with prob q, bluff with 1-q.
    Assumes hero always loses vs value and always wins vs bluff.
    """
    q = value_prob
    return q * (-bet) + (1 - q) * (pot + bet)


def min_bluff_freq_to_call_profitable(pot: float, bet: float) -> float:
    """Minimum overall bluffing frequency B needed so that a call vs a polarized bet is breakeven.
    Derived: B* = bet / (pot + 2*bet).
    """
    return bet / (pot + 2 * bet)

from typing import Dict

def bayes_update_hand_distribution(prior: Dict[str, float],
                                   action_likelihood: Dict[str, float]) -> Dict[str, float]:
    """Single-step Bayesian update of a discrete hand distribution.
    prior: P(H=h) over hands (keys can be any identifiers, e.g. 'AhKh', 'range_bucket_1').
    action_likelihood: P(A=a | H=h) for each hand h given the observed action.
    Returns posterior proportional to prior[h]*action_likelihood[h], normalized.
    Hands not in action_likelihood are assumed to have likelihood 0.
    """
    unnorm = {}
    for h, p_h in prior.items():
        like = action_likelihood.get(h, 0.0)
        unnorm[h] = p_h * like
    z = sum(unnorm.values())
    if z == 0:
        # Degenerate; return prior as fallback
        return prior.copy()
    return {h: v / z for h, v in unnorm.items()}


def ev_against_distribution(payouts: Dict[str, float],
                            posterior: Dict[str, float]) -> float:
    """Compute EV of a fixed decision given posterior P(H=h) and payoff(h).
    payouts: payoff(d, h) for each hand h.
    posterior: P(H=h | info).
    """
    return sum(posterior.get(h, 0.0) * payouts.get(h, 0.0) for h in payouts)

def jam_or_fold_equity_threshold(stack: float, pot0: float) -> float:
    """Minimum equity needed to call an all-in of size `stack` into a pot `pot0`.
    Derived: E* = stack / (pot0 + 2*stack)."""
    return stack / (pot0 + 2 * stack)


def jam_call_ev(equity: float, stack: float, pot0: float) -> float:
    """EV of calling an all-in (relative to folding) with equity E vs shover's range.
    EV_call = E*(pot0 + stack) - (1-E)*stack."""
    E = equity
    return E * (pot0 + stack) - (1 - E) * stack

def bayes_range_update(prior, likelihoods):
    """Single-step range update.
    prior: dict hand->P(h)
    likelihoods: dict hand->P(observed_action | h)
    returns posterior dict hand->P(h | action)
    """
    unnorm = {}
    for h, p_h in prior.items():
        lh = likelihoods.get(h, 0.0)
        unnorm[h] = p_h * lh
    Z = sum(unnorm.values())
    if Z == 0:
        return {h: 0.0 for h in prior}
    return {h: v / Z for h, v in unnorm.items()}

