def proportion_confidence_interval(phat, n, z=1.96):
    if n == 0:
        return (None, None)
    se = math.sqrt(phat * (1 - phat) / n)
    return (phat - z * se, phat + z * se)

def posterior_strong_given_tell(prior_strong, p_t_given_strong, p_t_given_weak):
    prior_weak = 1 - prior_strong
    if prior_weak <= 0:
        return 1.0
    lr = p_t_given_strong / p_t_given_weak if p_t_given_weak > 0 else float('inf')
    prior_odds = prior_strong / prior_weak
    post_odds = prior_odds * lr
    return post_odds / (1 + post_odds)

