def best_response_binary(EV_call_func, EV_fold_func, x):
    """Return villain's best response ('call', 'fold', or 'indifferent') at a given x.
    EV_call_func, EV_fold_func: callables in x.
    """
    ev_c = EV_call_func(x)
    ev_f = EV_fold_func(x)
    if ev_c > ev_f:
