def find_indifference(EV_call_func, EV_fold_func, x0):
    """Find x* where EV_call(x*) = EV_fold(x*), starting from initial guess x0.
    Requires mpmath and continuity around root.
    """
    import mpmath as mp
    f = lambda t: EV_call_func(t) - EV_fold_func(t)
    return mp.findroot(f, x0)

def odds_evens_B_EV(x):
    """Player B's EV in Odds and Evens vs a nemesis that always plays the majority action.
    x is probability B chooses 0 pennies.
    """
    if x > 0.5:
        # nemesis plays 0
        return 1.0 - 2.0 * x
    elif x < 0.5:
        # nemesis plays 1
        return 2.0 * x - 1.0
    else:
        return 0.0

