def jam_fold_game2_case1_threshold(S: float):
    """Attacker threshold y for Game #2 when S < 3 (best hand has 2/3 equity).
    Returns jam cutoff y in [0,1] where attacker jams for h >= y, defender always calls.
    """
    if S <= 0 or S >= 3:
        raise ValueError("This case is defined only for 0 < S < 3.")
    return (2.0 * S + 3.0) / (4.0 * S)

def jam_fold_game2_EV_attacker(S: float) -> float:
    """Equilibrium EV to attacker for Game #2 over all S>0 regions."""
    if S <= 0:
        raise ValueError("S must be positive")
    if S <= 1.5:
        return 0.0
    if S <= 3.0:
        return (2.0 * S - 3.0) / (48.0 * S)
    # S >= 3
    return -0.5 + 27.0 * S / (4.0 * (S + 3.0)**2)

def effective_stack(S: float, p_best: float) -> float:
    """Return effective stack S_eff given nominal S and showdown win prob p_best of the better hand.
    Uses S_eff = (2*p_best - 1) * S. For p_best in [0.5,1]."""
    if not (0.5 <= p_best <= 1.0):
        raise ValueError("p_best must be in [0.5, 1]")
    return (2.0 * p_best - 1.0) * S

def fictitious_update(S_old, S_new, t):
    """One fictitious-play style update step with harmonic m_t = 1/t.
    S_old, S_new: dict mapping information-set keys to dicts of action->prob.
    Returns updated strategy dict.
    """
    m = 1.0 / t
    S_next = {}
    for I in S_old.keys() | S_new.keys():
        a_old = S_old.get(I, {})
        a_new = S_new.get(I, {})
        actions = set(a_old) | set(a_new)
        S_next[I] = {}
        for a in actions:
            p_old = a_old.get(a, 0.0)
            p_new = a_new.get(a, 0.0)
            S_next[I][a] = (1 - m) * p_old + m * p_new
        # renormalize small numeric drift
        s = sum(S_next[I].values())
        if s > 0:
            for a in S_next[I]:
                S_next[I][a] /= s
    return S_next

def defender_call_threshold(S):
    """Equity threshold for defender to call an all-in given stack S.
    Returns minimum required equity x such that calling is >= 0 EV.
    """
    return (S - 1.0) / (2.0 * S)

def attacker_jam_threshold_vs_call_all(S):
    """Equity threshold for attacker to jam preflop vs a defender who calls all hands.
    Returns minimum required equity y such that jamming is >= 0 EV.
    """
    return (S - 0.5) / (2.0 * S)

def defender_equity_threshold_generic(S, call_cost):
    """Minimum equity needed to call vs shove given stack S and call_cost.
    Final pot assumed to be 2S.
    """
    return call_cost / (2.0 * S)

def ev_jam(S, B, p_fold, equity):
    """EV of jamming for attacker in a jam-or-fold model.
    S: effective stack in BB (amount attacker risks when called)
    B: defender blind already in pot (in same units as S)
    p_fold: prob defender folds vs jam
    equity: attacker's equity when called
    """
    p_call = 1.0 - p_fold
    return p_fold * B + p_call * S * (2.0 * equity - 1.0)


def ev_raise_fold(R, B, p_reraise):
    """EV of raising to R and folding vs a jam.
    R: raise size risked (in same units as B)
    B: defender blind already in pot
    p_reraise: prob defender jams over the raise
    """
    return (1.0 - p_reraise) * B + p_reraise * (-R)


def jam_or_fold_threshold(B, p_fold, equity, R, p_reraise, S_min=1.0, S_max=50.0, tol=1e-4, max_iter=100):
    """Numerically approximate S where EV_jam(S) == EV_raise_fold.
    Returns S*, or None if not bracketed.
    """
    from math import isfinite

    def f(S):
        return ev_jam(S, B, p_fold, equity) - ev_raise_fold(R, B, p_reraise)

    lo, hi = S_min, S_max
    f_lo, f_hi = f(lo), f(hi)
    if f_lo == 0:
        return lo
    if f_hi == 0:
        return hi
    if f_lo * f_hi > 0:
        return None
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        f_mid = f(mid)
        if not isfinite(f_mid):
            return None
        if abs(f_mid) < tol:
            return mid
        if f_mid * f_lo > 0:
            lo, f_lo = mid, f_mid
        else:
            hi, f_hi = mid, f_mid
    return 0.5 * (lo + hi)

