def auction_equilibrium_distributions(S, y0):
    """Return x(s), y(s) functions for the clairvoyant auction game with stack S and winner fraction y0.
    x(s): fraction of X's hands bidding at least s.
    y(s): fraction of Y's hands bidding at least s (value+bluff), clipped to [0,1].
    """
    def x(s):
        return 1.0 / math.sqrt(1.0 + 2.0 * s)
    ky = y0 * math.sqrt(1.0 + 2.0 * S)
    def y(s):
        val = ky / math.sqrt(1.0 + 2.0 * s)
        return max(0.0, min(1.0, val))
    return x, y

