def risk_of_ruin_from_alpha(bankroll_units: float, alpha: float, ev: float) -> float:
    """Risk of ruin R(b) = exp(-alpha * b) for a +EV game.
    If ev <= 0, model gives R=1 (certain ruin in infinite horizon);
    if alpha<=0 but ev>0, caller likely mis-specified alpha.
    bankroll_units: bankroll expressed in same units used to define X.
    alpha: RoR constant for this game (alpha>0 for +EV games with downside).
    ev: expectation per trial in the same units as X.
    """
    if bankroll_units <= 0:
        return 1.0
    if ev <= 0:
        return 1.0
    if alpha <= 0:
        # Degenerate per this model; treat as full ruin as a safeguard
        return 1.0
    return math.exp(-alpha * bankroll_units)

