def ror_with_uncertain_mu(w: float, s: float, N: int, bankroll: float,
                          num_points: int = 201, k: float = 5.0) -> float:
    """Approximate R_eff(b) = E_mu[R(b|mu)] where
    mu ~ Normal(w, s^2/N), via numeric integration (Gauss-Legendre-like midpoint rule).

    num_points: number of integration points (odd preferred)
    k: integrate over [w - k*SE, w + k*SE]
    """
    if N <= 0:
        raise ValueError("N must be positive")
    if s <= 0:
        raise ValueError("s must be positive")

    se = s / math.sqrt(N)
    mu_min = w - k * se
    mu_max = w + k * se

    def normal_pdf(mu: float) -> float:
        z = (mu - w) / se
        return math.exp(-0.5 * z * z) / (se * math.sqrt(2.0 * math.pi))

    # Midpoint integration
    h = (mu_max - mu_min) / num_points
    acc = 0.0
    for i in range(num_points):
        mu_i = mu_min + (i + 0.5) * h
        acc += ror_conditional(mu_i, s, bankroll) * normal_pdf(mu_i)
    return acc * h

