def kelly_utility_change(bankroll: float, outcomes: Iterable[float], probs: Iterable[float]) -> float:
    """Expected change in Kelly utility E[ln(B+x)] - ln(B). outcomes, probs are aligned.
    Assumes B + x > 0 for all x.
    """
    B = bankroll
    ev_ln = 0.0
    for x, p in zip(outcomes, probs):
        ev_ln += p * math.log(B + x)
    return ev_ln - math.log(B)

def certainty_equivalent_from_ln(outcomes: Iterable[float], probs: Iterable[float]) -> float:
    """Return CE for a bankroll-less gamble with outcomes o and probs p via ln utility.
    ln(CE) = E[ln(o)], so CE = exp(E[ln(o)]). All outcomes must be > 0.
    """
    ev_ln = 0.0
    for o, p in zip(outcomes, probs):
        if o <= 0:
            raise ValueError("All outcomes must be positive for ln utility.")
        ev_ln += p * math.log(o)
    return math.exp(ev_ln)

