def equity_from_exact_p(v, p):
    """E = sum p_i v_i."""
    return sum(vi*pi for vi, pi in zip(v, p))

def equity_from_cum_p(v, q):
    """E = sum q_i w_i using incremental ladder w from v."""
    w = incremental_ladder(v)
    return sum(qi*wi for qi, wi in zip(q, w))

def landrum_burns_equity(x, payouts):
    """Landrum–Burns equity for one player with win prob x and payouts v_1..v_n.
    Returns E[X]."""
    n = len(payouts)
    v1 = payouts[0]
    if n == 1:
        return x * v1
    rest_sum = sum(payouts[1:])
    return x * v1 + (1 - x) * rest_sum / (n - 1)

def landrum_burns_all(x_list, payouts):
    """Landrum–Burns equities for all players with win probs x_i summing to 1."""
    return [landrum_burns_equity(xi, payouts) for xi in x_list]

def tournament_equity_from_p(p_row, payouts):
    """Given p_row[j]=Prob(finishes j+1) and payouts v_1..v_n, return equity."""
    return sum(pj*vj for pj, vj in zip(p_row, payouts))

def tournament_equity_from_q(q_row, payouts):
    w = incremental_ladder(payouts)
    return sum(qj*wj for qj, wj in zip(q_row, w))

def tournament_variance_multiple(v: list[float]) -> float:
    """Compute k = sum(v_i^2) from a payout fraction vector v.

    v: list of payout fractions vi, summing to ~1 over all paid positions.
    Returns k as in the text (Σ vi^2).
    """
    return sum(vi * vi for vi in v)

def per_tournament_Z_variance(k: float, omega: float) -> float:
    """Approximate Var(Z) from k and ω using the book’s model.

    k: variance multiple (Σ vi^2)
    omega: normalized win rate ω
    """
    return (k - 1.0 - omega) * (1.0 + omega)

def estimate_k_from_sample(omega_obs: float, var_Z_obs: float) -> float:
    """Estimate k from observed normalized win rate and variance.

    omega_obs: observed ω_R
    var_Z_obs: observed variance of Z (s_R^2)
    """
    return (omega_obs + var_Z_obs) / (1.0 + omega_obs)

def bubble_penalty_chips(delta_payout: float, total_chips: float, total_prize_pool: float) -> float:
    """Approximate chip-equivalent penalty for busting before a given payout jump.

    delta_payout: $ or buy-in units gained by moving up one place.
    total_chips: total chips in tournament.
    total_prize_pool: total $ or buy-in units in pool.
    """
    if total_prize_pool <= 0:
        raise ValueError("total_prize_pool must be positive")
    return delta_payout * (total_chips / total_prize_pool)

import math


def doubles_needed(total_chips: float, stack: float) -> float:
    """Number of ideal doubles needed to go from stack to all chips T.
    N(x) = log2(T / x).
    """
    if stack <= 0 or total_chips <= 0:
        raise ValueError("Stacks and total_chips must be positive")
    return math.log2(total_chips / stack)


def equity_theory_of_doubling(total_chips: float, stack: float, C: float, prize_pool: float) -> float:
    """Approximate $EV from Theory of Doubling Up.

    C: per-double success probability (skill parameter).
    """
    if not (0 < C < 1):
        raise ValueError("C must be between 0 and 1")
    N = doubles_needed(total_chips, stack)
    return prize_pool * (C ** N)


def addon_value_theory_of_doubling(total_chips: float, stack: float, delta_stack: float, C: float, prize_pool: float) -> float:
    """Incremental EV of buying delta_stack extra chips at same C.
    Positive result means the chips are worth more (in EV) than their par cost.
    """
    if delta_stack <= 0:
        raise ValueError("delta_stack must be positive")
    ev_before = equity_theory_of_doubling(total_chips, stack, C, prize_pool)
    ev_after = equity_theory_of_doubling(total_chips, stack + delta_stack, C, prize_pool)
    return ev_after - ev_before

def chip_fraction_equity(chips: float, total_chips: float, total_prize_pool: float) -> float:
    """Approximate prize equity when chip fraction maps linearly to prize fraction."""
    if total_chips <= 0:
        raise ValueError("total_chips must be positive")
    return (chips / total_chips) * total_prize_pool

def min_fold_freq_for_immediate_profit(raise_size: float, small_blind: float, big_blind: float, ante: float, n_players: int) -> float:
    """Return minimum p_fold such that EV_raise >= 0 in the one-step model.
    Assumes we win only when everyone folds, and lose full raise when called.
    """
    dead = small_blind + big_blind + n_players * ante
    return raise_size / (dead + raise_size)

import math
from typing import List, Tuple

def binomial_pmf(n: int, k: int, p: float) -> float:
    return math.comb(n, k) * (p ** k) * ((1 - p) ** (n - k))

def series_virtual_tournament_distribution(T: int, p_win: float) -> List[Tuple[int, float]]:
    """Return (n_wins, probability) for n_wins in 0..T under Binomial(T, p_win)."""
    return [(n, binomial_pmf(T, n, p_win)) for n in range(T + 1)]

def choose_with_aggression_bias(ev_passive: float, ev_aggressive: float, bias: float = 0.0) -> str:
    """Tie-break between passive and aggressive actions with optional aggression bias.
    bias: lambda >= 0; if >0, favors aggression when EVs are close.
    Returns 'passive' or 'aggressive'."""
    if ev_aggressive + bias > ev_passive:
        return 'aggressive'
    else:
        return 'passive'
